plugin.policy:
package ratify.policy

default valid := false

cosign_artifact_types := {
  "application/vnd.dev.cosign.artifact.sig.v1+json",
  "application/vnd.dev.sigstore.bundle.v0.3+json",
}

valid {
  cosign_verified
  not other_artifact_failed
}

# at least one cosign signature, legacy or bundle, MUST pass the verification
cosign_verified {
  report := input.verifierReports[_]
  cosign_artifact_types[report.artifactType]
  not failed_verify(report)
}

# every other artifact MUST pass the verification
other_artifact_failed {
  report := input.verifierReports[_]
  not cosign_artifact_types[report.artifactType]
  failed_verify(report)
}

# a report fails if any verifier report, including nested ones, fails
failed_verify(report) {
  [path, value] := walk(report)
  value == false
  path[count(path) - 1] == "isSuccess"
}

# a report fails if an artifact has no verifier report
failed_verify(report) {
  [path, value] := walk(report)
  path[count(path) - 1] == "verifierReports"
  count(value) == 0
}
